using System;using System.Reflection;using System.Threading.Tasks;
namespace AshkanSocial.Core.Services{
public sealed class SignalRRealtimeClient:IRealtimeClient{
 readonly RealtimeSettings settings;object connection;Type hubType;string userId;
 public RealtimeConnectionState State{get;private set;}=RealtimeConnectionState.Disconnected;
 public event Action<RealtimeConnectionState> StateChanged;public event Action<string,string,string> DirectMessageReceived;public event Action<string,string,bool> TypingChanged;public event Action<string,bool> PresenceChanged;public event Action<string,string,string> GroupMessageReceived;public event Action<string> NotificationReceived;
 internal void DispatchDirect(string from,string to,string text){DirectMessageReceived?.Invoke(from,to,text);}internal void DispatchTyping(string from,string to,bool typing){TypingChanged?.Invoke(from,to,typing);}internal void DispatchPresence(string id,bool online){PresenceChanged?.Invoke(id,online);}internal void DispatchGroup(string groupId,string from,string text){GroupMessageReceived?.Invoke(groupId,from,text);}internal void DispatchNotification(string text){NotificationReceived?.Invoke(text);}
 public bool ClientPackageAvailable{get{return Type.GetType("Microsoft.AspNetCore.SignalR.Client.HubConnectionBuilder, Microsoft.AspNetCore.SignalR.Client")!=null;}}
 public SignalRRealtimeClient(RealtimeSettings settings){this.settings=settings??new RealtimeSettings();}
 void Set(RealtimeConnectionState s){State=s;StateChanged?.Invoke(s);}
 public async Task ConnectAsync(string id){userId=id;if(!settings.Enabled){Set(RealtimeConnectionState.Disabled);return;}var builderType=Type.GetType("Microsoft.AspNetCore.SignalR.Client.HubConnectionBuilder, Microsoft.AspNetCore.SignalR.Client");if(builderType==null)throw new InvalidOperationException("Install Microsoft.AspNetCore.SignalR.Client to enable the real-time WinForms transport.");Set(RealtimeConnectionState.Connecting);dynamic builder=Activator.CreateInstance(builderType);var ext=Type.GetType("Microsoft.AspNetCore.SignalR.Client.HubConnectionBuilderExtensions, Microsoft.AspNetCore.SignalR.Client.Core");if(ext==null)throw new InvalidOperationException("SignalR client extensions were not found.");var withUrl=ext.GetMethod("WithUrl",new[]{builderType,typeof(string)});if(withUrl==null)throw new InvalidOperationException("Compatible SignalR WithUrl API was not found.");builder=withUrl.Invoke(null,new object[]{builder,settings.HubUrl});connection=builder.Build();hubType=connection.GetType();await InvokeTask("StartAsync");await SendCore("JoinUser",new object[]{userId});Set(RealtimeConnectionState.Connected);}
 async Task InvokeTask(string name){var m=hubType.GetMethod(name,new[]{typeof(System.Threading.CancellationToken)});if(m!=null){await (Task)m.Invoke(connection,new object[]{default(System.Threading.CancellationToken)});return;}m=hubType.GetMethod(name,Type.EmptyTypes);if(m!=null)await (Task)m.Invoke(connection,null);}
 async Task SendCore(string method,object[] args){if(connection==null)return;var methods=hubType.GetMethods();foreach(var m in methods){if((m.Name=="SendCoreAsync"||m.Name=="InvokeCoreAsync")&&m.GetParameters().Length>=2){try{var result=m.Invoke(connection,new object[]{method,args,default(System.Threading.CancellationToken)});if(result is Task)await (Task)result;return;}catch{}}}}
 public async Task DisconnectAsync(){if(connection!=null)await InvokeTask("StopAsync");Set(RealtimeConnectionState.Disconnected);}
 public Task SendDirectMessageAsync(string id,string from,string to,string text){return SendCore("SendDirectMessage",new object[]{new {Id=id,FromUserId=from,ToUserId=to,Text=text,CreatedAt=DateTime.UtcNow}});}
 public Task SendTypingAsync(string from,string to,bool typing){return SendCore("Typing",new object[]{new {FromUserId=from,ToUserId=to,IsTyping=typing}});}
 public Task SendGroupMessageAsync(string id,string groupId,string from,string text){return SendCore("SendGroupMessage",new object[]{new {Id=id,GroupId=groupId,FromUserId=from,Text=text,CreatedAt=DateTime.UtcNow}});}
 public Task JoinGroupAsync(string groupId){return SendCore("JoinGroup",new object[]{groupId});}
 public void Dispose(){try{DisconnectAsync().Wait(1000);}catch{}}
}}
